package com.savora.api; import com.savora.model.*; import com.savora.repo.*; import jakarta.transaction.Transactional; import org.springframework.data.domain.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/orders") public class OrderController { final OrderRepo orders;final UserRepo users;final FoodRepo foods;final AddressRepo addresses; public OrderController(OrderRepo o,UserRepo u,FoodRepo f,AddressRepo a){orders=o;users=u;foods=f;addresses=a;} User user(Authentication a){return users.findByEmail(a.getName()).orElseThrow();} @GetMapping Api<?> list(Authentication a,@RequestParam(defaultValue="0")int page){return Api.ok(orders.findByUserIdOrderByCreatedAtDesc(user(a).id,PageRequest.of(page,10)));} @PostMapping @Transactional Api<?> checkout(Authentication a,@RequestBody Checkout input){if(input.items()==null||input.items().isEmpty())throw new IllegalArgumentException("Cart cannot be empty");var u=user(a);var lines=input.items().stream().map(l->Map.entry(foods.findById(l.foodId()).orElseThrow(()->new NoSuchElementException("Food not found")),l.quantity())).toList();var restaurant=lines.get(0).getKey().restaurant;if(lines.stream().anyMatch(x->!x.getKey().restaurant.id.equals(restaurant.id)))throw new IllegalArgumentException("Order items must belong to one restaurant");BigDecimal subtotal=lines.stream().map(x->x.getKey().price.multiply(BigDecimal.valueOf(x.getValue()))).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal discount="SAVORA10".equalsIgnoreCase(input.coupon())?subtotal.multiply(new BigDecimal(".10")):BigDecimal.ZERO;var o=new Order();o.user=u;o.restaurant=restaurant;o.address=input.addressId()==null?null:addresses.findById(input.addressId()).orElseThrow();o.subtotal=subtotal;o.tax=subtotal.multiply(new BigDecimal(".05"));o.deliveryFee=restaurant.deliveryFee;o.discount=discount;o.coupon=input.coupon();o.total=o.subtotal.add(o.tax).add(o.deliveryFee).subtract(discount);orders.save(o);for(var line:lines){var i=new OrderItem();i.order=o;i.food=line.getKey();i.name=i.food.name;i.price=i.food.price;i.quantity=line.getValue();o.items.add(i);}return Api.ok(orders.save(o));} @GetMapping("/{id}") Api<?> one(Authentication a,@PathVariable Long id){var o=orders.findById(id).orElseThrow();if(!o.user.id.equals(user(a).id))throw new SecurityException("Forbidden");return Api.ok(o);} }
